    "  finally { parser.close(); }",
    "}",
    // Compaction cannot hide raw replay storage from the stream's buffer bound.
    "for (const fragments of [false, true]) {",
    '  const run = ambiguous => { const options = { maxBuffer: 128, maxRetained: 65536 }; const parser = createStreamParser(fragments ? { ...options, select: select([["a"]], { fragments: decodedFragments }) } : options); let failed; let last; const consume = items => { for (const item of items) { last = item; if (!item.ok) failed = item.failure; } };',
    '    try { consume(parser.feed(\'{"kept":1,"a":"body\' + (ambiguous ? String.fromCharCode(39) + "," : ""))); for (let i = 0; i < 100 && failed === undefined; i++) consume(parser.feed("\\\\u0061")); if (failed === undefined) { consume(parser.feed(\'"}\')); consume(parser.end()); } return { failed, last }; }',
    "    finally { parser.close(); } };",
    '  const bad = run(true); const good = run(false); if (bad.failed?.kind !== "limit-reached" || bad.failed.resource !== "buffer" || bad.failed.limit !== 128 || bad.failed.recovered?.complete !== false || (!fragments && bad.failed.recovered.value.kept !== 1)) throw new Error("released quote-replay source bypassed buffer limit or lost recovery");',
