    'const queuedStop = createStreamParser({ select: select([["a"]], { fragments: decodedFragments }), summary: true, maxBuffer: 128, maxRetained: 1024 });',
    'try { queuedStop.feed(\'{"a":"small"}{"a":"body\' + String.fromCharCode(39) + "," + "x".repeat(32768)); const items = Array.from(queuedStop.feed("{}")); const parts = items.filter(item => "ok" in item && item.ok).map(item => item.value); const failed = items.find(item => "ok" in item && !item.ok)?.failure; const summary = items.at(-1);',
    '  if (parts.filter(part => part.kind === "data").map(part => part.text).join("") !== "smallbody" || parts.filter(part => part.kind === "end").length !== 1 || failed?.kind !== "limit-reached" || failed.resource !== "retained" || failed.recovered?.cut?.kind !== "string" || failed.recovered.cut.path.length !== 1 || failed.recovered.cut.path[0] !== "a" || summary?.kind !== "summary" || summary.complete || summary.roots !== 2 || summary.matches !== 2 || summary.unmatched.length !== 0) throw new Error("scanner disposal lost queued recovery, cut or summary");',
    "} finally { queuedStop.close(); }",
    'const pausedStop = createStreamParser({ select: select([["a"]], { fragments: decodedFragments }), summary: true, maxBuffer: 128, maxRetained: 1024 });',
