    '    if (failed?.ok !== false || failed.failure.kind !== "limit-reached" || before.ok || before.failure.kind !== "limit-reached" || before.failure.recovered?.complete !== false || before.failure.recovered.cut.kind !== "string" || !isDeepStrictEqual(before.failure.recovered.cut.path, ["b"])) throw new Error("stopped view lost failure or cut");',
    '    const value = before.failure.recovered.value; const prefix = "body" + String.fromCharCode(39) + "," + "x".repeat(selected ? 9 : 6); if (selected ? value.length !== 2 || value[0].value !== 1 || !isDeepStrictEqual(value[0].path, ["a"]) || value[1].value !== prefix || !isDeepStrictEqual(value[1].path, ["b"]) : value.a !== 1 || value.b !== prefix) throw new Error("stopped view lost bounded recovered content");',
