    '  try { const first = Array.from(prefixStream.feed(\'{"a":"body\' + String.fromCharCode(39) + ",")); const text = items => items.filter(item => item.ok && item.value.kind === "data").map(item => item.value.text).join(""); if (text(first) !== "body" || first.some(item => item.ok && item.value.kind === "end")) throw new Error("decided quote prefix did not leave before settlement");',
